function removeElement(nums: number[], val: number): number {
  // k — индекс, куда записываем следующий «оставляемый» элемент
  let k = 0;

  for (let i = 0; i < nums.length; i++) {
    if (nums[i] !== val) {
      // Элемент нужно оставить — переносим его в начало массива
      nums[k] = nums[i];
      k++;
    }
    // Иначе просто пропускаем: элемент «удалён»
  }

  // Первые k элементов — все значения, не равные val
  return k;
}

// Время: O(n) — один проход
// Память: O(1) — меняем массив на месте
